  btState: ["Sensor's own Bluetooth", "Bluetooth propio del sensor", "Eigenes Bluetooth des Sensors", "Bluetooth propre du capteur", "Bluetooth proprio del sensore", "センサー自身のBluetooth", "传感器自带蓝牙", "Bluetooth próprio do sensor"],
  btOpen: ["OPEN", "ABIERTO", "OFFEN", "OUVERT", "APERTO", "開放", "开启", "ABERTO"],
  btClosed: ["closed", "cerrado", "geschlossen", "fermé", "chiuso", "閉鎖", "已关闭", "fechado"],
